#!/usr/bin/env python3
# Writes the .clangd that makes clangd understand the ESP NIC sources.
import json
import subprocess
import sys
from pathlib import Path

esp_nic_dir = Path(__file__).resolve().parent
project_root = esp_nic_dir.parent.parent

HEADER = """\
# Generated by gen_clangd.py, do not edit.
CompileFlags:
  Compiler: clang++
  Remove: [-m*, -fstrict-volatile-bitfields, -fno-tree-switch-conversion]
  Add:
    - -D__XTENSA__=1
    - -U__linux__
"""

FRAGMENT = """
---
If:
  PathMatch: .*/({stems})\\.cpp
CompileFlags:
  CompilationDatabase: {build_dir}
  Add:
{includes}
"""


def system_includes(compiler):
    log = subprocess.run([compiler, '-E', '-x', 'c++', '-', '-v'],
                         input='',
                         capture_output=True,
                         text=True,
                         check=True).stderr.splitlines()
    first = log.index('#include <...> search starts here:') + 1
    last = log.index('End of search list.')
    return [Path(line.strip()).resolve() for line in log[first:last]]


if __name__ == '__main__':
    # A source can be described by several build directories, newest wins.
    databases = sorted(
        project_root.glob('build/*/esp*-nic-build/compile_commands.json'),
        key=lambda path: path.stat().st_mtime)
    entries = {
        entry['file']: entry
        for database in databases
        for entry in json.loads(database.read_text())
        if str(esp_nic_dir) in entry['file']
    }
    if not entries:
        sys.exit()

    toolchains = {}
    for entry in entries.values():
        key = (entry['command'].split()[0], entry['directory'])
        toolchains.setdefault(key, []).append(Path(entry['file']).stem)

    config = HEADER
    for (compiler, build_dir), stems in sorted(toolchains.items()):
        config += FRAGMENT.format(
            stems='|'.join(sorted(stems)),
            build_dir=build_dir,
            includes='\n'.join(f'    - -isystem{include}'
                               for include in system_includes(compiler)))

    (esp_nic_dir / '.clangd').write_text(config)
